<script lang="ts">
  import {onMount,tick,untrack} from 'svelte';
  import type {PageData} from './$types';
  import {filterRows,observedRanges,changedRangeBounds,dominatorsByGroup,paretoTiersByGroup,comparable,value,metricLabel,kemMetrics,sigMetrics,comparisonKey,type Metric,type RecordRow,type RangeFilters} from '$lib/analysis';
  let {data}:{data:PageData}=$props();
  let theme=$state<'dark'|'light'>('light');
  let compact=$state(false),mobileFiltersOpen=$state(false);
  onMount(()=>{
    theme=document.documentElement.dataset.theme==='light'?'light':'dark';
    const media=window.matchMedia('(max-width: 700px)');
    const update=()=>compact=media.matches;
    update();media.addEventListener('change',update);
    return ()=>media.removeEventListener('change',update);
  });
  function toggleTheme(){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('ngcc-theme',theme);localStorage.setItem('theme',theme)}
  const contributeUrl=(import.meta.env.VITE_CONTRIBUTE_URL as string|undefined)?.trim() || 'https://github.com/zhengjieyu/ngcc-benchmark-explorer';
  const all=$derived(data.dataset.records as unknown as RecordRow[]);
  let tab=$state<'KEM'|'Signature'|'Pareto'>('KEM');
  let paretoType=$state<'KEM'|'Signature'>('KEM');
  let platform=$state('x86_1'), implementation=$state('reference');
  let enabledAlgorithms=$state<string[]>(untrack(()=>[...new Set(all.filter(r=>r.type==='KEM').map(r=>r.algorithm))]));
  let enabledSecurityGroups=$state<string[]>(['NGCC-128','NGCC-256','NGCC-512','spec-192','spec-384','spec-unclassified']);
  const familyDomain=['lattice','code','isogeny','hash','symmetric/MPCitH','multivariate','other'];
  const strengthDomain=['128-bit','192-bit','256-bit','384-bit','512-bit','Not stated'];
  const strengthColors=['#60a5fa','#34d399','#fb923c','#c084fc','#f87171','#94a3b8'];
  const familyShapes=['square','diamond','circle','cross','triangle-up','triangle-down','triangle-left'];
  const familySymbols=['■','◆','●','✚','▲','▼','◀'];
  const rangeKeys=['public_key_bytes','secret_key_bytes','ciphertext_bytes','signature_bytes','pk_ct_bytes','pk_sig_bytes','keygen_cycles','encap_cycles','decap_cycles','sign_cycles','verify_cycles','keygen_ms','encap_ms','decap_ms','sign_ms','verify_ms'];
  const defaultRangesByType=untrack(()=>({KEM:observedRanges(data.dataset.records as unknown as RecordRow[],'KEM',rangeKeys),Signature:observedRanges(data.dataset.records as unknown as RecordRow[],'Signature',rangeKeys)}));
  let ranges=$state<RangeFilters>(structuredClone(defaultRangesByType.KEM));
  let x=$state<Metric>('pk_ct_bytes'), y=$state<Metric>('decap_cycles');
  let logAxes=$state(true), showOnlyFrontier=$state(false);
  let selected=$state<RecordRow|null>(null), sortMetric=$state<Metric>('decap_cycles'), ascending=$state(true);
  let chartEl:HTMLDivElement;
  const type=$derived(tab==='Pareto'?paretoType:tab);
  const metrics=$derived(type==='KEM'?kemMetrics:sigMetrics);
  const algorithms=$derived([...new Set(all.filter(r=>r.type===type).map(r=>r.algorithm))].sort());
  const categories=$derived([...new Set(all.filter(r=>r.type===type).map(r=>r.category).filter((c):c is string=>!!c))].sort());
  const schemeGroups=$derived(categories.map(c=>({category:c,algorithms:[...new Set(all.filter(r=>r.type===type&&r.category===c).map(r=>r.algorithm))].sort()})));
  const sizeFields=$derived(type==='KEM'?[{key:'public_key_bytes',label:'Public key'},{key:'secret_key_bytes',label:'Secret key'},{key:'ciphertext_bytes',label:'Ciphertext'},{key:'pk_ct_bytes',label:'Public key + ciphertext'}]:[{key:'public_key_bytes',label:'Public key'},{key:'secret_key_bytes',label:'Secret key'},{key:'signature_bytes',label:'Signature'},{key:'pk_sig_bytes',label:'Public key + signature'}]);
  const cycleFields=$derived(type==='KEM'?[{key:'keygen_cycles',label:'Key generation'},{key:'encap_cycles',label:'Encapsulation'},{key:'decap_cycles',label:'Decapsulation'}]:[{key:'keygen_cycles',label:'Key generation'},{key:'sign_cycles',label:'Signing'},{key:'verify_cycles',label:'Verification'}]);
  const timeFields=$derived(type==='KEM'?[{key:'keygen_ms',label:'Key generation'},{key:'encap_ms',label:'Encapsulation'},{key:'decap_ms',label:'Decapsulation'}]:[{key:'keygen_ms',label:'Key generation'},{key:'sign_ms',label:'Signing'},{key:'verify_ms',label:'Verification'}]);
  const activeRanges=$derived(changedRangeBounds(ranges,defaultRangesByType[type]));
  const filtered=$derived(filterRows(all,{type,security:'all',platform,implementation,algorithm:'all',algorithms:enabledAlgorithms,securityGroups:enabledSecurityGroups,ranges:activeRanges}));
  const eligible=$derived(filtered.filter(r=>tab==='Pareto'?comparable(r,x,y):[x,y].every(m=>value(r,m)!=null&&(!m.endsWith('_cycles')||!r.measurements[m]?.kat_not_passed))));
  const dominators=$derived(dominatorsByGroup(filtered,x,y));
  const paretoTiers=$derived(paretoTiersByGroup(filtered,x,y));
  const frontierIds=$derived(new Set([...dominators].filter(([,peers])=>peers.length===0).map(([id])=>id)));
  const chartRows=$derived(tab==='Pareto'&&showOnlyFrontier?eligible.filter(r=>frontierIds.has(r.id)):eligible);
  const chartStrengths=$derived(strengthDomain.filter(level=>chartRows.some(r=>strength(r)===level)));
  const chartFamilies=$derived(familyDomain.filter(f=>chartRows.some(r=>(r.category??'other')===f)));
  const sorted=$derived([...filtered].sort((a,b)=>{if(tab==='Pareto'){const ta=paretoTiers.get(a.id)??Infinity,tb=paretoTiers.get(b.id)??Infinity;if(ta!==tb)return ta-tb;}const av=value(a,sortMetric),bv=value(b,sortMetric);return (av==null?1:bv==null?-1:(av-bv)*(ascending?1:-1))||a.algorithm.localeCompare(b.algorithm)}));
  const configCount=$derived(new Set(eligible.filter(r=>r.security_group).map(comparisonKey)).size);
  function resetSchemes(next:'KEM'|'Signature'){enabledAlgorithms=[...new Set(all.filter(r=>r.type===next).map(r=>r.algorithm))];ranges=structuredClone(defaultRangesByType[next]);}
  function toggleAlgorithm(name:string){enabledAlgorithms=enabledAlgorithms.includes(name)?enabledAlgorithms.filter(a=>a!==name):[...enabledAlgorithms,name];}
  function toggleCategory(names:string[]){const allOn=names.every(n=>enabledAlgorithms.includes(n));enabledAlgorithms=allOn?enabledAlgorithms.filter(n=>!names.includes(n)):[...new Set([...enabledAlgorithms,...names])];}
  function toggleSecurity(name:string){enabledSecurityGroups=enabledSecurityGroups.includes(name)?enabledSecurityGroups.filter(g=>g!==name):[...enabledSecurityGroups,name];}
  function setTab(next:'KEM'|'Signature'|'Pareto'){tab=next;selected=null;resetSchemes(next==='Pareto'?paretoType:next);if(next==='KEM'){x='pk_ct_bytes';y='decap_cycles';sortMetric=y}else if(next==='Signature'){x='signature_bytes';y='verify_cycles';sortMetric=y}}
  function setParetoType(next:'KEM'|'Signature'){paretoType=next;resetSchemes(next);selected=null;x=next==='KEM'?'pk_ct_bytes':'signature_bytes';y=next==='KEM'?'decap_cycles':'verify_cycles';sortMetric=y;}
  function strength(r:RecordRow){const bits=r.security_group?Number(r.security_group.replace('NGCC-','')):r.spec_classical_target_bits;return bits?`${bits}-bit`:'Not stated'}
  function fmt(n:number|null|undefined){return n==null?'—':new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(n)}
  function source(file:string,kind:'blob'|'tree'='blob'){return `https://github.com/ngcc-dev/ngcc-harness/${kind}/${data.dataset.source_commit}/${file.split('/').map(encodeURIComponent).join('/')}`}
  $effect(()=>{const rows=chartRows,front=frontierIds,mx=x,my=y,log=logAxes,el=chartEl,tradeOff=tab==='Pareto',light=theme==='light',small=compact;if(!el)return;let disposed=false;void (async()=>{await tick();if(disposed||!chartEl)return;const embed=(await import('vega-embed')).default;const chartBg=light?'#ffffff':'#1b1f2e',chartText=light?'#626262':'#a5afc3',chartTitle=light?'#1a1a1a':'#dde3ed',chartGrid=light?'#e2e2df':'#303649',pointStroke=light?'#ffffff':'#1b1f2e',highlightStroke=light?'#1a1a1a':'#ffffff';const visibleFamilies=familyDomain.filter(f=>rows.some(r=>(r.category??'other')===f));const visibleShapes=visibleFamilies.map(f=>familyShapes[familyDomain.indexOf(f)]);const visibleStrengths=strengthDomain.filter(level=>rows.some(r=>strength(r)===level));const visibleStrengthColors=visibleStrengths.map(level=>strengthColors[strengthDomain.indexOf(level)]);const points=rows.map(r=>({id:r.id,algorithm:r.algorithm,parameter_set:r.parameter_set,platform:r.platform,implementation:r.implementation,category:r.category??'other',strength:strength(r),x:value(r,mx),y:value(r,my),pareto:front.has(r.id)?'No better alternative on these two metrics':'Has a better alternative on these two metrics'}));el.innerHTML='';if(!points.length)return;const result=await embed(el,{width:'container',height:small?320:400,background:chartBg,padding:{left:small?3:10,right:small?5:30,top:small?8:20,bottom:small?8:15},data:{values:points},mark:{type:'point',filled:true},encoding:{x:{field:'x',type:'quantitative',title:metricLabel[mx],scale:{type:log?'log':'linear',zero:false},axis:small?{tickCount:4,format:'~s',grid:false}:undefined},y:{field:'y',type:'quantitative',title:metricLabel[my],scale:{type:log?'log':'linear',zero:false},axis:small?{tickCount:4,format:'~s',grid:false}:undefined},color:{field:'strength',type:'nominal',scale:{domain:visibleStrengths,range:visibleStrengthColors},legend:small?null:{orient:'right',title:'Classical strength (claimed)',titleColor:chartTitle,labelColor:chartText}},shape:{field:'category',type:'nominal',scale:{domain:visibleFamilies,range:visibleShapes},legend:small?null:{orient:'right',title:'Problem family',titleColor:chartTitle,labelColor:chartText,symbolFillColor:chartText,symbolStrokeColor:chartText}},stroke:tradeOff?{condition:{test:"datum.pareto === 'No better alternative on these two metrics'",value:highlightStroke},value:pointStroke}:{value:pointStroke},strokeWidth:tradeOff?{condition:{test:"datum.pareto === 'No better alternative on these two metrics'",value:2.5},value:0.8}:{value:0.8},opacity:tradeOff?{condition:{test:"datum.pareto === 'No better alternative on these two metrics'",value:1},value:.18}:{value:.9},size:tradeOff?{condition:{test:"datum.pareto === 'No better alternative on these two metrics'",value:190},value:90}:{value:125},tooltip:[{field:'algorithm'},{field:'parameter_set'},{field:'strength',title:'Claimed classical strength'},{field:'category',title:'Problem family'},{field:'x',title:metricLabel[mx],format:',.0f'},{field:'y',title:metricLabel[my],format:',.0f'},...(tradeOff?[{field:'pareto',title:'Two-metric comparison'}]:[])]},config:{axis:{labelColor:chartText,titleColor:chartTitle,gridColor:chartGrid,labelFontSize:small?10:12,titleFontSize:small?11:13},legend:{labelColor:chartText,titleColor:chartTitle},view:{stroke:null}}},{actions:false});result.view.addEventListener('click',(_e:unknown,item:{datum?:{id?:string}}|null|undefined)=>{const hit=all.find(r=>r.id===item?.datum?.id);if(hit)selected=hit;});})();return()=>{disposed=true;};});
</script>
<svelte:head><title>NGCC Explorer · Benchmark evidence</title><meta name="description" content="Explore published NGCC Round 1 benchmarks and Pareto trade-offs." /></svelte:head>
<div class="min-h-screen"><header class="site-header border-b border-[var(--border)] bg-[var(--header)]"><div class="site-header-inner"><a class="site-brand" href="https://zhengjieyu.github.io/">Jieyu Zheng <span class="muted">/</span> NGCC Explorer</a><nav class="site-nav" aria-label="Site navigation"><a href="https://zhengjieyu.github.io/">Home</a><a href="https://zhengjieyu.github.io/#projects">Projects</a><button type="button" onclick={toggleTheme} aria-label={theme==='dark'?'Switch to light mode':'Switch to dark mode'}>{theme==='dark'?'☀ Light':'☾ Dark'}</button><a class="contribute-link" href={contributeUrl} target="_blank" rel="noreferrer">Contribute ↗</a></nav></div></header>
<main class="site-main mx-auto max-w-7xl px-4 sm:px-6 py-6 sm:py-9"><section class="site-hero mb-8"><div class="label mb-4">Research tool · NGCC Round 1</div><h1 class="text-4xl md:text-5xl max-w-3xl">Explore the trade-offs behind <br /><span class="text-[var(--accent)]">next-generation cryptography.</span></h1><p class="mt-5 muted max-w-3xl">Published independent ngcc-harness measurements, linked to their source records. Comparison groups reflect submitted targets, not independently validated security guarantees.</p><p class="text-xs muted mt-4">{data.dataset.records.length} benchmark records · checked daily for upstream updates</p></section>
<nav class="view-nav flex gap-2 mb-6" aria-label="Views">{#each ['KEM','Signature','Pareto'] as name}<button class:active={tab===name} onclick={()=>setTab(name as typeof tab)}>{name==='Pareto'?'Trade-off analysis':name==='KEM'?'KEM explorer':'Signature explorer'}</button>{/each}</nav>
<button type="button" class="filters-toggle" aria-expanded={mobileFiltersOpen} aria-controls="explorer-filters" onclick={()=>mobileFiltersOpen=!mobileFiltersOpen}>Filters <span aria-hidden="true">{mobileFiltersOpen?'−':'+'}</span><span class="muted">{filtered.length} results</span></button>
<div class="grid lg:grid-cols-[300px_minmax(0,1fr)] gap-5"><aside id="explorer-filters" class="filter-panel card p-4 sm:p-5 self-start max-h-[calc(100vh-2rem)] overflow-y-auto sticky top-4" class:mobile-open={mobileFiltersOpen}>
  <h2 class="text-lg font-semibold mb-4">Filters</h2>
  {#if tab==='Pareto'}<label class="block text-sm mb-4">Primitive<select class="control w-full mt-1" bind:value={paretoType} onchange={(e)=>setParetoType(e.currentTarget.value as 'KEM'|'Signature')}><option>KEM</option><option>Signature</option></select></label>{/if}
  <details class="border-t border-[var(--border-strong)] pt-4"><summary class="label cursor-pointer mb-3">Schemes ({enabledAlgorithms.length}/{algorithms.length})</summary><div class="flex justify-end mb-3"><div class="text-xs flex gap-3"><button class="text-[var(--accent)] underline" onclick={()=>enabledAlgorithms=[...algorithms]}>All</button><button class="text-[var(--accent)] underline" onclick={()=>enabledAlgorithms=[]}>None</button></div></div>
  {#each schemeGroups as group}<div class="mb-3"><label class="flex items-center gap-2 font-semibold text-sm"><input type="checkbox" checked={group.algorithms.every(a=>enabledAlgorithms.includes(a))} onchange={()=>toggleCategory(group.algorithms)} /> {group.category}</label><div class="pl-5 mt-1 space-y-1">{#each group.algorithms as name}<label class="flex items-start gap-2 text-sm muted"><input type="checkbox" class="mt-1" checked={enabledAlgorithms.includes(name)} onchange={()=>toggleAlgorithm(name)} /><span>{name}</span></label>{/each}</div></div>{/each}</details>
  <div class="border-t border-[var(--border-strong)] pt-4 mt-4"><div class="label mb-3">Claimed classical security strength</div>{#each [['NGCC-128','128-bit'],['spec-192','192-bit'],['NGCC-256','256-bit'],['spec-384','384-bit'],['NGCC-512','512-bit'],['spec-unclassified','Not stated']] as group}<label class="flex items-center gap-2 text-sm mb-2"><input type="checkbox" checked={enabledSecurityGroups.includes(group[0])} onchange={()=>toggleSecurity(group[0])} />{group[1]}</label>{/each}<p class="text-xs muted mt-2">ICCS requires 128, 256 and 512 bits of classical security; 384 bits is optional. The 192-bit entries are extra submission variants. Values shown here are claims, not independent validation. <a class="underline" href="https://www.niccs.org.cn/niccs/Notice/1975896137741635584/lDop1mav.pdf" target="_blank" rel="noreferrer">ICCS submission requirements ↗</a></p></div>
  <div class="border-t border-[var(--border-strong)] pt-4 mt-4"><div class="label mb-3">Measurement configuration</div><label class="block text-sm mb-4">Hardware platform<select class="control w-full mt-1" bind:value={platform}><option value="all">All platforms</option><option value="x86_1">Intel Core i7-12700</option><option value="arm_1">Snapdragon X Elite</option></select></label><label class="block text-sm mb-4">Implementation<select class="control w-full mt-1" bind:value={implementation}><option value="all">All variants</option><option value="reference">Reference</option><option value="optimized-avx2">Optimized AVX2</option></select></label></div>
  <div class="border-t border-[var(--border-strong)] pt-4 mt-4"><div class="label mb-3">Sizes · bytes</div><p class="text-xs muted mb-3">Initial values show the observed full-data range. Edit a bound to filter.</p>{#each sizeFields as field}<div class="mb-3 text-xs muted"><div class="mb-1">{field.label}</div><div class="grid grid-cols-2 gap-2"><label>Min<input aria-label={'Min '+field.label+' bytes'} type="number" min="0" class="control w-full mt-1" placeholder="Min" bind:value={ranges[field.key].min} /></label><label>Max<input aria-label={'Max '+field.label+' bytes'} type="number" min="0" class="control w-full mt-1" placeholder="Max" bind:value={ranges[field.key].max} /></label></div></div>{/each}</div>
  <div class="border-t border-[var(--border-strong)] pt-4 mt-4"><div class="label mb-3">Performance · cycles</div><p class="text-xs muted mb-3">Initial values show the observed full-data range. Edit a bound to filter.</p>{#each cycleFields as field}<div class="mb-3 text-xs muted"><div class="mb-1">{field.label}</div><div class="grid grid-cols-2 gap-2"><label>Min<input aria-label={'Min '+field.label+' cycles'} type="number" min="0" class="control w-full mt-1" placeholder="Min" bind:value={ranges[field.key].min} /></label><label>Max<input aria-label={'Max '+field.label+' cycles'} type="number" min="0" class="control w-full mt-1" placeholder="Max" bind:value={ranges[field.key].max} /></label></div></div>{/each}</div>
  <div class="border-t border-[var(--border-strong)] pt-4 mt-4"><div class="label mb-3">Performance · ms</div><p class="text-xs muted mb-3">Initial values show the observed full-data range. Edit a bound to filter.</p>{#each timeFields as field}<div class="mb-3 text-xs muted"><div class="mb-1">{field.label}</div><div class="grid grid-cols-2 gap-2"><label>Min<input aria-label={'Min '+field.label+' milliseconds'} type="number" min="0" step="any" class="control w-full mt-1" placeholder="Min" bind:value={ranges[field.key].min} /></label><label>Max<input aria-label={'Max '+field.label+' milliseconds'} type="number" min="0" step="any" class="control w-full mt-1" placeholder="Max" bind:value={ranges[field.key].max} /></label></div></div>{/each}</div>
  <div class="border-t border-[var(--border-strong)] pt-4 text-xs muted">{filtered.length} matching records<br />{eligible.length} complete X/Y pairs{#if tab==='Pareto'}<br />{frontierIds.size} with no better alternative on these two metrics{/if}</div>
</aside>
<div class="space-y-5 min-w-0"><section class="card p-5 min-w-0"><div class="flex justify-between gap-4 flex-wrap mb-5"><div><div class="label">{tab==='Pareto'?'Two-metric comparison':'Performance map'}</div><h2 class="text-xl font-semibold mt-1">{tab==='Pareto'?`${type}: two-metric trade-offs`:`${type} results`}</h2></div><div class="axis-selectors flex gap-3 flex-wrap"><label class="text-xs muted">X axis<select class="control block mt-1" bind:value={x}>{#each metrics as m}<option value={m}>{metricLabel[m]}</option>{/each}</select></label><label class="text-xs muted">Y axis<select class="control block mt-1" bind:value={y}>{#each metrics as m}<option value={m}>{metricLabel[m]}</option>{/each}</select></label></div></div><div class="flex gap-5 flex-wrap mb-3"><label class="text-xs muted flex items-center gap-2"><input type="checkbox" bind:checked={logAxes} /> Logarithmic axes</label>{#if tab==='Pareto'}<label class="text-xs muted flex items-center gap-2"><input type="checkbox" bind:checked={showOnlyFrontier} /> Show only points with no better alternative</label>{/if}</div>{#if tab==='Pareto'}<div class="rounded-lg border border-[var(--border)] bg-[var(--surface-raised)] p-4 mb-4"><div class="flex gap-6 flex-wrap mb-2"><div><strong class="text-xl text-[var(--accent)]">{frontierIds.size}</strong><span class="text-xs muted ml-2">no better alternative</span></div><div><strong class="text-xl">{eligible.length-frontierIds.size}</strong><span class="text-xs muted ml-2">with a better alternative</span></div></div><p class="text-sm mb-1">Layer 1 contains the two-metric trade-offs: no other comparable result is better on one selected metric without being worse on the other. Remove Layer 1 and repeat to obtain Layer 2, Layer 3, and so on. Results within a layer are not ordered.</p><p class="text-xs muted mb-0">Comparisons are made only within the same claimed strength, machine and implementation configuration. Changing either axis changes the result.</p></div><div class="text-xs text-[var(--text-warning)] mb-3">Layers are calculated separately within each 128/256/512-bit claimed-strength group, machine, implementation, build profile and compiler flags. Different groups do not compete. The 192/384-bit variants are excluded. {configCount} comparable configuration group(s). Records with missing metrics or failed KAT are unranked.</div><p class="text-xs mb-4"><a class="text-[var(--accent)] underline" href="https://zhengjieyu.github.io/blog/ngcc-tradeoff-guide/" target="_blank" rel="noreferrer">How do the two metrics and trade-off layers work? Read the guide (EN / 中文) ↗</a></p>{:else}<div class="text-xs muted mb-3">Each point is a measured result with both selected metrics. The initial Y axis uses decapsulation for KEMs and verification for signatures as examples of recipient-side work; these are display defaults, not an overall ranking. Choose any available metric on either axis. Records with missing metrics or a failed KAT are excluded.</div>{/if}<div bind:this={chartEl} class="chart-container min-h-[320px] sm:min-h-[400px]">{#if eligible.length===0}<div class="grid place-items-center h-[400px] muted">No complete X/Y measurements for these filters.</div>{/if}</div><div class="mobile-chart-legend"><div><strong>Claimed strength</strong><div class="mobile-legend-items">{#each chartStrengths as level}<span><i class="strength-dot" style:background={strengthColors[strengthDomain.indexOf(level)]}></i>{level}</span>{/each}</div></div><div><strong>Problem family</strong><div class="mobile-legend-items">{#each chartFamilies as family}<span><i class="family-symbol">{familySymbols[familyDomain.indexOf(family)]}</i>{family}</span>{/each}</div></div></div><p class="text-xs muted mt-3">Color shows claimed classical strength; shape shows the problem family. {#if tab==='Pareto'}Larger, outlined points have no better alternative within their comparison group; dim points have at least one. Use the checkbox above to isolate the former.{/if} Lower left is better for both selected metrics. Click a point for its source record.</p></section>
<section class="results-section card overflow-hidden"><div class="results-heading px-5 py-4 border-b border-[var(--border)] flex justify-between items-center"><div><div class="label">Evidence table</div><h2 class="font-semibold">{tab==='Pareto'?'Results by trade-off layer':`${type} results`}</h2></div><span class="text-xs muted">{tab==='Pareto'?'Layer 1 first; layers are separate for each security and test configuration.':'Click a row for provenance'}</span></div><div class="desktop-results overflow-x-auto max-h-[550px]"><table class="w-full min-w-[1200px] text-sm text-left whitespace-nowrap"><thead class="sticky top-0 bg-[var(--table-head)] text-[var(--table-head-text)]"><tr><th class="p-3">Algorithm / parameter</th><th class="p-3">Category</th><th class="p-3 min-w-[240px]">Assumption</th><th class="p-3">Claimed classical strength</th><th class="p-3"><button onclick={()=>{sortMetric=x;ascending=sortMetric===x?!ascending:true}}>{metricLabel[x]} ↕</button></th><th class="p-3"><button onclick={()=>{sortMetric=y;ascending=sortMetric===y?!ascending:true}}>{metricLabel[y]} ↕</button></th>{#if tab==='Pareto'}<th class="p-3 min-w-[140px]" title="Trade-off layer based on the currently selected X and Y metrics, within the same security and test configuration">Trade-off layer</th>{/if}</tr></thead><tbody>{#each sorted as r}<tr class="border-t border-[var(--border)] hover:bg-[var(--row-hover)] cursor-pointer" onclick={()=>selected=r}><td class="p-3"><div class="font-medium">{r.algorithm}</div><div class="text-xs muted">{r.parameter_set}</div></td><td class="p-3">{r.category??'Unknown'}</td><td class="p-3 min-w-[240px] max-w-[240px] whitespace-normal text-xs leading-snug" title={r.assumption??'Unclassified'}>{r.assumption??'Unknown'}</td><td class="p-3">{strength(r)}</td><td class="p-3 font-mono">{fmt(value(r,x))}</td><td class="p-3 font-mono">{fmt(value(r,y))}</td>{#if tab==='Pareto'}<td class="p-3">{#if paretoTiers.has(r.id)}<span class={paretoTiers.get(r.id)===1?'text-[var(--accent)] font-bold':'muted'} title="Calculated from the selected X and Y metrics within the same security and test configuration">Layer {paretoTiers.get(r.id)}</span>{#if (dominators.get(r.id)?.length??0)>0}<div class="mt-1 max-w-[260px] whitespace-normal text-xs muted">Better on these two metrics: {#each (dominators.get(r.id)??[]).slice(0,2) as peer, i}{i>0?', ':''}{peer.algorithm} · {peer.parameter_set}{/each}{#if (dominators.get(r.id)?.length??0)>2} · +{(dominators.get(r.id)?.length??0)-2} more{/if}. Click the row to see their values.</div>{/if}{:else}<span class="muted" title="Missing a comparison group, a selected metric, or a passing KAT">Unranked</span>{/if}</td>{/if}</tr>{/each}</tbody></table></div><div class="mobile-results" role="list" aria-label="Benchmark results">{#each sorted as r}<div role="listitem"><button type="button" class="mobile-result" onclick={()=>selected=r}><span class="mobile-result-head"><strong>{r.algorithm}</strong>{#if tab==='Pareto'}<span class:frontier-badge={paretoTiers.get(r.id)===1} class="layer-badge">{paretoTiers.has(r.id)?`Layer ${paretoTiers.get(r.id)}`:'Unranked'}</span>{/if}</span><span class="mobile-result-param">{r.parameter_set}</span><span class="mobile-result-meta">{strength(r)} · {r.category??'Unknown'}</span><span class="mobile-result-metrics"><span><small>{metricLabel[x]}</small><b>{fmt(value(r,x))}</b></span><span><small>{metricLabel[y]}</small><b>{fmt(value(r,y))}</b></span></span></button></div>{/each}</div></section></div></div>
<p class="text-xs muted mt-8">Data: <a class="underline hover:text-[var(--text)]" href="https://github.com/ngcc-dev/ngcc-harness">ngcc-dev/ngcc-harness</a> · independent Round 1 campaign · last imported {data.dataset.synced_utc.slice(0,10)} · checked daily for upstream updates</p></main></div>
{#if selected}<div class="fixed inset-0 z-20 bg-black/70 flex justify-end" role="presentation" onclick={()=>selected=null}><div class="details-panel h-full w-full max-w-lg bg-[var(--surface)] border-l border-[var(--border-strong)] p-4 sm:p-6 overflow-y-auto" role="dialog" tabindex="-1" aria-modal="true" aria-label="Algorithm details" onclick={(e)=>e.stopPropagation()} onkeydown={(e)=>e.stopPropagation()}><button class="detail-close float-right text-2xl" aria-label="Close" onclick={()=>selected=null}>×</button><div class="label mb-2">{selected.type} · benchmark record</div><h2 class="text-2xl font-semibold mb-1">{selected.algorithm}</h2><p class="muted mb-5">{selected.parameter_set} · {strength(selected)} claimed classical strength</p><div class="rounded-lg bg-[var(--surface-raised)] p-4 mb-5"><div class="label">Category</div><div class="font-medium">{selected.category??'Unknown'}</div><div class="label mt-3">Assumption / hard problem</div><div class="text-sm">{selected.assumption??'Not classified'}</div>{#if selected.classification_source}<a class="text-xs text-[var(--accent)] underline" href={selected.classification_source} target="_blank" rel="noreferrer">Classification source ↗</a>{/if}</div><div class="text-xs text-[var(--text-warning)] mb-5">{#if selected.security_group_origin==='target-table'}The displayed strength comes from the benchmark target table. {#if selected.security_target_match==='normalized-name'}The source name ({selected.security_target_instance}) was matched after punctuation normalization.{/if} <a class="underline" href={source('performance/security_targets.csv')} target="_blank" rel="noreferrer">Inspect target table ↗</a>{:else if selected.spec_claim_source}The displayed strength comes from the submitted specification. {selected.spec_claim_note} <a class="underline" href={source(selected.spec_claim_source)} target="_blank" rel="noreferrer">Read specification ↗</a>{/if} These values are claims, not independent security validation.</div>{#if tab==='Pareto'}<div class="rounded-lg bg-[var(--surface-raised)] p-4 mb-5"><div class="label mb-2">Two-metric comparison</div>{#if !comparable(selected,x,y)}<p class="text-sm muted">No comparison: this record has no 128/256/512-bit comparison group, a selected metric is missing, or a KAT did not pass.</p>{:else if (dominators.get(selected.id)?.length??0)===0}<p class="text-sm">No visible result has a lower value on one selected metric without a higher value on the other.</p>{:else}<p class="text-sm mb-2">{dominators.get(selected.id)?.length} alternatives have values no higher on both selected metrics and a lower value on at least one. This row: {metricLabel[x]} = {fmt(value(selected,x))}; {metricLabel[y]} = {fmt(value(selected,y))}.</p><div class="text-xs font-semibold mb-2">Better results in this comparison group</div>{#each dominators.get(selected.id)??[] as peer}<button class="block w-full text-left text-sm text-[var(--accent)] underline mb-2" onclick={()=>selected=peer}>{peer.algorithm} · {peer.parameter_set}<span class="block text-xs muted no-underline">{metricLabel[x]}: {fmt(value(peer,x))} · {metricLabel[y]}: {fmt(value(peer,y))}</span></button>{/each}{/if}</div>{/if}<div class="rounded-lg border border-[var(--border-strong)] bg-[var(--surface-raised)] p-4 mb-5"><div class="label mb-2">Implementation source code</div><div class="text-sm space-y-2">{#if selected.source_directory}<div><a class="text-[var(--accent)] underline" href={source(selected.source_directory,'tree')} target="_blank" rel="noreferrer">Open implementation code on GitHub ↗</a></div>{:else}<div class="muted">Exact implementation source path is not available for this variant.</div>{/if}<div><a class="text-[var(--accent)] underline" href={source(selected.candidate_directory,'tree')} target="_blank" rel="noreferrer">Open candidate directory ↗</a></div></div></div><div class="grid grid-cols-2 gap-3 mb-5">{#each [['Public key',selected.public_key_bytes],['Secret key',selected.secret_key_bytes],['Ciphertext',selected.ciphertext_bytes],['Shared secret',selected.shared_secret_bytes],['Signature',selected.signature_bytes]] as item}<div class="rounded-lg bg-[var(--surface-raised)] p-3"><div class="label">{item[0]} · bytes</div><div class="text-lg font-semibold">{fmt(item[1] as number|null)}</div></div>{/each}</div><div class="label mb-2">Measurements & original records</div>{#each Object.entries(selected.measurements) as [metric,m]}<div class="border-t border-[var(--border-strong)] py-3 flex justify-between gap-3"><div><div>{metricLabel[metric as Metric]??metric}</div><div class="text-xs muted">KAT {m.kat??'unknown'}{m.kat_not_passed?' · not passed':''}</div></div><a class="text-[var(--accent)] underline font-mono" href={source(m.source_file)} target="_blank" rel="noreferrer">{fmt(m.cycles)} ↗</a></div>{/each}<div class="label mt-5 mb-2">Configuration</div><p class="text-sm muted">{selected.hardware}<br />{selected.implementation} · {selected.build_profile}<br /><span class="break-all">{selected.build_flags}</span></p><div class="label mt-5 mb-2">Size & target provenance</div><div class="text-sm">{#each selected.metadata_sources as file}<div><a class="text-[var(--accent)] underline" href={source(file)} target="_blank" rel="noreferrer">{file} ↗</a></div>{/each}</div><div class="label mt-5 mb-2">Missing / failed</div>{#if selected.missing.length}{#each selected.missing as m}<p class="text-sm muted">{m.metric}: {m.reason}</p>{/each}{:else}<p class="text-sm muted">None recorded.</p>{/if}<p class="text-xs muted mt-6">Size basis: {selected.size_basis??'not listed'} · Source commit: <span class="font-mono break-all">{selected.source_commit}</span></p></div></div>{/if}
